package org.humanjourney.core.mapfeature;
import java.util.*;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import org.humanjourney.core.geography.DiscoveryLedger;
import org.humanjourney.core.water.WaterGeography.Point;
/** Feature protocol2: small features batch normally; a large feature is bounded serialized fragments. */
public final class FeaturePackets {
 public static final int PER_PACKET=4,REMOVALS=64,MAX_BYTES=48*1024,MAX_PARTS=4096,MAX_FEATURES=2048,CHUNK_BYTES=16*1024,MAX_FEATURE_BYTES=288*1024,MAX_TRANSFER_BYTES=24*1024*1024;
 public enum Mode{FULL,DELTA,CLEAR}public enum Request{INSTANCE}
 public record Header(UUID session,long sequence,long discovery,long catalog){public Header{if(session==null||sequence<=0||discovery<0||catalog<0)throw new IllegalArgumentException("invalid feature revision");}}
 public record Fragment(String id,int index,int count,int length,byte[] data){public Fragment{data=data.clone();if(!DiscoveryLedger.validId(id)||length<1||length>MAX_FEATURE_BYTES||count!=(length+CHUNK_BYTES-1)/CHUNK_BYTES||index<0||index>=count||data.length!=Math.min(CHUNK_BYTES,length-index*CHUNK_BYTES))throw new IllegalArgumentException("invalid feature fragment");}@Override public byte[] data(){return data.clone();}@Override public boolean equals(Object o){return o instanceof Fragment f&&id.equals(f.id)&&index==f.index&&count==f.count&&length==f.length&&Arrays.equals(data,f.data);}@Override public int hashCode(){return Objects.hash(id,index,count,length,Arrays.hashCode(data));}}
 public record Frame(Header header,Mode mode,long base,int part,int parts,List<MapFeature.View> features,List<String> removals,String error,List<Fragment> fragments){
  public Frame(Header h,Mode m,long b,int p,int n,List<MapFeature.View> f,List<String> r,String e){this(h,m,b,p,n,f,r,e,List.of());}
  public Frame{features=List.copyOf(features);removals=List.copyOf(removals);fragments=List.copyOf(fragments);if(error==null){Objects.requireNonNull(header);Objects.requireNonNull(mode);if(parts<1||parts>MAX_PARTS||part<0||part>=parts||features.size()>PER_PACKET||removals.size()>REMOVALS||fragments.size()>1||!fragments.isEmpty()&&(!features.isEmpty()||!removals.isEmpty())||base<0||mode==Mode.DELTA&&(base==0||base>=header.sequence())||mode!=Mode.DELTA&&base!=0||mode==Mode.FULL&&!removals.isEmpty()||mode==Mode.CLEAR&&(parts!=1||!features.isEmpty()||!removals.isEmpty()||!fragments.isEmpty()))throw new IllegalArgumentException("invalid feature transfer bounds");for(var f:features)if(f.geometry().vertexCount()>512)throw new IllegalArgumentException("large feature requires fragments");for(String id:removals)if(!DiscoveryLedger.validId(id))throw new IllegalArgumentException("invalid removed feature ID");}}
  public static Frame bad(String error){return new Frame(null,Mode.FULL,0,0,1,List.of(),List.of(),error);}public boolean valid(){return error==null;}
 }
 private static int count(FriendlyByteBuf b,int max){int n=b.readVarInt();if(n<0||n>max)throw new IllegalArgumentException("feature count outside bounds");return n;}
 private static void points(FriendlyByteBuf b,List<Point> points){b.writeVarInt(points.size());for(var p:points){b.writeDouble(p.x());b.writeDouble(p.z());}}
 private static final class ReadBudget{int vertices,rings;}
 private static List<Point> points(FriendlyByteBuf b,ReadBudget budget){int n=count(b,FeatureGeometry.MAX_VERTICES);budget.vertices+=n;if(budget.vertices>FeatureGeometry.MAX_VERTICES)throw new IllegalArgumentException("feature vertex budget exceeded");var out=new ArrayList<Point>();for(int i=0;i<n;i++)out.add(new Point(b.readDouble(),b.readDouble()));return out;}
 private static FeatureGeometry.Ring ring(FriendlyByteBuf b,ReadBudget budget){if(++budget.rings>FeatureGeometry.MAX_RINGS)throw new IllegalArgumentException("feature ring budget exceeded");return new FeatureGeometry.Ring(points(b,budget));}
 private static void part(FriendlyByteBuf b,FeatureGeometry.Part p){points(b,p.outer().points());b.writeVarInt(p.holes().size());for(var h:p.holes())points(b,h.points());}
 private static FeatureGeometry.Part part(FriendlyByteBuf b,ReadBudget budget){var outer=ring(b,budget);int holes=count(b,FeatureGeometry.MAX_RINGS-1);var list=new ArrayList<FeatureGeometry.Ring>();for(int i=0;i<holes;i++)list.add(ring(b,budget));return new FeatureGeometry.Part(outer,list);}
 private static void view(FriendlyByteBuf b,MapFeature.View v){b.writeUtf(v.id(),64);b.writeUtf(v.label(),128);b.writeVarInt(v.type().ordinal());b.writeUtf(v.dimension(),256);b.writeVarInt(v.priority());b.writeVarInt(v.geometry().kind().ordinal());if(v.geometry().kind()==FeatureGeometry.Kind.POLYLINE)points(b,v.geometry().points());else{b.writeVarInt(v.geometry().parts().size());for(var p:v.geometry().parts())part(b,p);}}
 private static MapFeature.View view(FriendlyByteBuf b){String id=b.readUtf(64),label=b.readUtf(128);int type=count(b,MapFeature.Type.values().length-1);String dimension=b.readUtf(256);int priority=b.readVarInt(),kind=count(b,FeatureGeometry.Kind.values().length-1);var budget=new ReadBudget();FeatureGeometry geometry;if(FeatureGeometry.Kind.values()[kind]==FeatureGeometry.Kind.POLYLINE)geometry=FeatureGeometry.polyline(points(b,budget));else{int size=count(b,FeatureGeometry.MAX_RINGS);var parts=new ArrayList<FeatureGeometry.Part>();for(int i=0;i<size;i++)parts.add(part(b,budget));geometry=FeatureGeometry.Kind.values()[kind]==FeatureGeometry.Kind.POLYGON?(parts.size()==1?FeatureGeometry.polygon(parts.getFirst()):failGeometry()):FeatureGeometry.multipolygon(parts);}return new MapFeature.View(id,label,MapFeature.Type.values()[type],dimension,priority,geometry);}
 private static FeatureGeometry failGeometry(){throw new IllegalArgumentException("invalid polygon part count");}
 private static byte[] serialize(MapFeature.View v){var b=new FriendlyByteBuf(io.netty.buffer.Unpooled.buffer());try{view(b,v);if(b.readableBytes()>MAX_FEATURE_BYTES)throw new IllegalArgumentException("feature exceeds serialized byte limit");var bytes=new byte[b.readableBytes()];b.readBytes(bytes);return bytes;}finally{b.release();}}
 public static final StreamCodec<RegistryFriendlyByteBuf,Frame> CODEC=new StreamCodec<>(){
  public void encode(RegistryFriendlyByteBuf b,Frame f){if(!f.valid())throw new IllegalArgumentException("rejected feature frame");int start=b.writerIndex();var h=f.header();b.writeUUID(h.session());b.writeVarLong(h.sequence());b.writeVarLong(h.discovery());b.writeVarLong(h.catalog());b.writeVarInt(f.mode().ordinal());b.writeVarLong(f.base());b.writeVarInt(f.part());b.writeVarInt(f.parts());b.writeVarInt(f.features().size());for(var v:f.features())view(b,v);b.writeVarInt(f.removals().size());for(String id:f.removals())b.writeUtf(id,64);b.writeVarInt(f.fragments().size());for(var c:f.fragments()){b.writeUtf(c.id(),64);b.writeVarInt(c.index());b.writeVarInt(c.count());b.writeVarInt(c.length());b.writeByteArray(c.data());}if(b.writerIndex()-start>MAX_BYTES)throw new IllegalArgumentException("feature packet exceeds byte limit");}
  public Frame decode(RegistryFriendlyByteBuf b){try{if(b.readableBytes()>MAX_BYTES)throw new IllegalArgumentException("feature packet too large");var h=new Header(b.readUUID(),b.readVarLong(),b.readVarLong(),b.readVarLong());int mode=count(b,Mode.values().length-1);long base=b.readVarLong();int part=b.readVarInt(),parts=b.readVarInt(),n=count(b,PER_PACKET);var features=new ArrayList<MapFeature.View>();for(int i=0;i<n;i++)features.add(view(b));var removed=new ArrayList<String>();n=count(b,REMOVALS);for(int i=0;i<n;i++)removed.add(b.readUtf(64));var fragments=new ArrayList<Fragment>();n=count(b,1);for(int i=0;i<n;i++)fragments.add(new Fragment(b.readUtf(64),b.readVarInt(),b.readVarInt(),b.readVarInt(),b.readByteArray(CHUNK_BYTES)));if(b.readableBytes()!=0)throw new IllegalArgumentException("unexpected feature bytes");return new Frame(h,Mode.values()[mode],base,part,parts,features,removed,null,fragments);}catch(RuntimeException error){b.skipBytes(b.readableBytes());return Frame.bad("Malformed feature packet: "+error.getClass().getSimpleName());}}
 };
 public static final StreamCodec<RegistryFriendlyByteBuf,Request> REQUEST=StreamCodec.unit(Request.INSTANCE);
 public static List<MapFeature.View> assemble(Collection<Fragment> fragments){var groups=new TreeMap<String,List<Fragment>>();long total=0;for(var c:fragments){total+=c.data.length;if(total>MAX_TRANSFER_BYTES)throw new IllegalArgumentException("fragment transaction too large");groups.computeIfAbsent(c.id(),id->new ArrayList<>()).add(c);}if(groups.size()>MAX_FEATURES)throw new IllegalArgumentException("too many fragmented features");var result=new ArrayList<MapFeature.View>();long vertices=0,rings=0;for(var group:groups.entrySet()){var first=group.getValue().getFirst();var slots=new Fragment[first.count()];for(var c:group.getValue()){if(c.count()!=first.count()||c.length()!=first.length()||slots[c.index()]!=null)throw new IllegalArgumentException("inconsistent/duplicate feature fragment");slots[c.index()]=c;}var bytes=new byte[first.length()];for(int i=0;i<slots.length;i++){if(slots[i]==null)throw new IllegalArgumentException("incomplete feature fragments");System.arraycopy(slots[i].data,0,bytes,i*CHUNK_BYTES,slots[i].data.length);}var b=new FriendlyByteBuf(io.netty.buffer.Unpooled.wrappedBuffer(bytes));try{var v=view(b);if(b.readableBytes()!=0||!v.id().equals(group.getKey()))throw new IllegalArgumentException("fragment identity/trailing bytes mismatch");vertices+=v.geometry().vertexCount();rings+=v.geometry().ringCount();if(vertices>FeatureGeometry.MAX_CATALOG_VERTICES||rings>FeatureGeometry.MAX_CATALOG_RINGS)throw new IllegalArgumentException("assembled geometry exceeds catalog budget");result.add(v);}finally{b.release();}}return List.copyOf(result);}
 private record Draft(List<MapFeature.View> features,List<String> removals,List<Fragment> fragments){}
 public static List<Frame> frames(Header h,Mode mode,long base,Collection<MapFeature.View> entries,Collection<String> removed){GeometryBudget.check(entries);if(removed.size()>MAX_FEATURES)throw new IllegalArgumentException("too many removals");var whole=new ArrayList<MapFeature.View>();var chunks=new ArrayList<Fragment>();long bytes=0;for(var v:entries){bytes+=v.geometry().vertexCount()*16L+v.geometry().ringCount()*8L;if(v.geometry().vertexCount()<=512)whole.add(v);else{var raw=serialize(v);int count=(raw.length+CHUNK_BYTES-1)/CHUNK_BYTES;for(int i=0;i<count;i++)chunks.add(new Fragment(v.id(),i,count,raw.length,Arrays.copyOfRange(raw,i*CHUNK_BYTES,Math.min(raw.length,(i+1)*CHUNK_BYTES))));}}if(bytes>MAX_TRANSFER_BYTES)throw new IllegalArgumentException("feature transaction too large");whole.sort(Comparator.comparing(MapFeature.View::id));chunks.sort(Comparator.comparing(Fragment::id).thenComparingInt(Fragment::index));var removals=new ArrayList<>(new TreeSet<>(removed));int groups=Math.max((whole.size()+PER_PACKET-1)/PER_PACKET,(removals.size()+REMOVALS-1)/REMOVALS);var drafts=new ArrayList<Draft>();for(int i=0;i<groups;i++){int a=Math.min(i*PER_PACKET,whole.size()),k=Math.min(i*REMOVALS,removals.size());drafts.add(new Draft(whole.subList(a,Math.min(a+PER_PACKET,whole.size())),removals.subList(k,Math.min(k+REMOVALS,removals.size())),List.of()));}for(var c:chunks)drafts.add(new Draft(List.of(),List.of(),List.of(c)));if(drafts.isEmpty())drafts.add(new Draft(List.of(),List.of(),List.of()));if(drafts.size()>MAX_PARTS)throw new IllegalArgumentException("too many feature transfer parts");var out=new ArrayList<Frame>();for(int i=0;i<drafts.size();i++){var d=drafts.get(i);out.add(new Frame(h,mode,base,i,drafts.size(),d.features(),d.removals(),null,d.fragments()));}return List.copyOf(out);}
 private FeaturePackets(){}
}
